        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the potential dereferencing of an invalid pointer (`xdst0`) in the error handling path of the `xfrm_bundle_create` function. When an error occurred, the code previously assigned an error pointer to `xdst0` and then used a `goto` statement to return a pointer to `xdst0`. If `xdst0` was not properly initialized or if it was null, this could lead to dereferencing an invalid pointer, resulting in undefined behavior or a crash.

        Commit message:
        xfrm Fix potential error pointer dereference in
 xfrm_bundle_create.

We may derference an invalid pointer in the error path of
xfrm_bundle_create(). Fix this by returning this error
pointer directly instead of assigning it to xdst0.

Fixes: 45b018beddb6 ("ipsec: Create and use new helpers for dst child access.")
Signed-off-by: Steffen Klassert <steffen.klassert@secunet.com>  

        Patch:

 static struct dst_entry *xfrm_bundle_create(struct xfrm_policy *policy,
 					    struct xfrm_state **xfrm,
 					    struct xfrm_dst **bundle,
 					    int nx,
 					    const struct flowi *fl,
 					    struct dst_entry *dst)
 {
 	struct net *net = xp_net(policy);
 	unsigned long now = jiffies;
 	struct net_device *dev;
 	struct xfrm_mode *inner_mode;
 	struct xfrm_dst *xdst_prev = NULL;
 	struct xfrm_dst *xdst0 = NULL;
 	int i = 0;
 	int err;
 	int header_len = 0;
 	int nfheader_len = 0;
 	int trailer_len = 0;
 	int tos;
 	int family = policy->selector.family;
 	xfrm_address_t saddr, daddr;

 	xfrm_flowi_addr_get(fl, &saddr, &daddr, family);

 	tos = xfrm_get_tos(fl, family);

 	dst_hold(dst);

 	for (; i < nx; i++) {
 		struct xfrm_dst *xdst = xfrm_alloc_dst(net, family);
 		struct dst_entry *dst1 = &xdst->u.dst;

 		err = PTR_ERR(xdst);
 		if (IS_ERR(xdst)) {
 			dst_release(dst);
 			goto put_states;
 		}

 		bundle[i] = xdst;
 		if (!xdst_prev)
 			xdst0 = xdst;
 		else
 			/* Ref count is taken during xfrm_alloc_dst()
 			 * No need to do dst_clone() on dst1
 			 */
 			xfrm_dst_set_child(xdst_prev, &xdst->u.dst);

 		if (xfrm[i]->sel.family == AF_UNSPEC) {
 			inner_mode = xfrm_ip2inner_mode(xfrm[i],
 							xfrm_af2proto(family));
 			if (!inner_mode) {
 				err = -EAFNOSUPPORT;
 				dst_release(dst);
 				goto put_states;
 			}
 		} else
 			inner_mode = xfrm[i]->inner_mode;

 		xdst->route = dst;
 		dst_copy_metrics(dst1, dst);

 		if (xfrm[i]->props.mode != XFRM_MODE_TRANSPORT) {
 			family = xfrm[i]->props.family;
 			dst = xfrm_dst_lookup(xfrm[i], tos, fl->flowi_oif,
 					      &saddr, &daddr, family,
 					      xfrm[i]->props.output_mark);
 			err = PTR_ERR(dst);
 			if (IS_ERR(dst))
 				goto put_states;
 		} else
 			dst_hold(dst);

 		dst1->xfrm = xfrm[i];
 		xdst->xfrm_genid = xfrm[i]->genid;

 		dst1->obsolete = DST_OBSOLETE_FORCE_CHK;
 		dst1->flags |= DST_HOST;
 		dst1->lastuse = now;

 		dst1->input = dst_discard;
 		dst1->output = inner_mode->afinfo->output;

 		xdst_prev = xdst;

 		header_len += xfrm[i]->props.header_len;
 		if (xfrm[i]->type->flags & XFRM_TYPE_NON_FRAGMENT)
 			nfheader_len += xfrm[i]->props.header_len;
 		trailer_len += xfrm[i]->props.trailer_len;
 	}

 	xfrm_dst_set_child(xdst_prev, dst);
 	xdst0->path = dst;

 	err = -ENODEV;
 	dev = dst->dev;
 	if (!dev)
 		goto free_dst;

 	xfrm_init_path(xdst0, dst, nfheader_len);
 	xfrm_init_pmtu(bundle, nx);

 	for (xdst_prev = xdst0; xdst_prev != (struct xfrm_dst *)dst;
 	     xdst_prev = (struct xfrm_dst *) xfrm_dst_child(&xdst_prev->u.dst)) {
 		err = xfrm_fill_dst(xdst_prev, dev, fl);
 		if (err)
 			goto free_dst;

 		xdst_prev->u.dst.header_len = header_len;
 		xdst_prev->u.dst.trailer_len = trailer_len;
 		header_len -= xdst_prev->u.dst.xfrm->props.header_len;
 		trailer_len -= xdst_prev->u.dst.xfrm->props.trailer_len;
 	}

-out:
 	return &xdst0->u.dst;

 put_states:
 	for (; i < nx; i++)
 		xfrm_state_put(xfrm[i]);
 free_dst:
 	if (xdst0)
 		dst_release_immediate(&xdst0->u.dst);
-	xdst0 = ERR_PTR(err);
-	goto out;
+
+	return ERR_PTR(err);
 }



